// src/pages/AdminDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";

// ---------------- Reusable Card Component ----------------
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

// ---------------- Pending Users Table ----------------
const PendingUsersTable = ({ users, onApprove, onReject }) => {
  if (users.length === 0)
    return <p style={{ color: "#777", fontStyle: "italic" }}>No pending users.</p>;

  return (
    <table style={{ width: "100%", borderCollapse: "collapse" }}>
      <thead>
        <tr style={{ background: "#f1f1f1" }}>
          <th style={{ padding: "8px", textAlign: "left" }}>Student #</th>
          <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
          <th style={{ padding: "8px", textAlign: "left" }}>Email</th>
          <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
        </tr>
      </thead>
      <tbody>
        {users.map((u) => (
          <tr key={u.id} style={{ borderTop: "1px solid #eee" }}>
            <td style={{ padding: "8px" }}>{u.studentNumber}</td>
            <td style={{ padding: "8px" }}>{u.name}</td>
            <td style={{ padding: "8px" }}>{u.email}</td>
            <td style={{ padding: "8px", textAlign: "center" }}>
              <button
                onClick={() => onApprove(u.id)}
                style={{
                  marginRight: "5px",
                  background: "#28a745",
                  color: "#fff",
                  border: "none",
                  borderRadius: "6px",
                  padding: "5px 10px",
                  cursor: "pointer",
                }}
              >
                Approve
              </button>
              <button
                onClick={() => onReject(u.id)}
                style={{
                  background: "#dc3545",
                  color: "#fff",
                  border: "none",
                  borderRadius: "6px",
                  padding: "5px 10px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

// ---------------- Candidates Table ----------------
const CandidatesTable = ({ candidates, onApprove, onDelete }) => {
  if (candidates.length === 0)
    return <p style={{ color: "#777", fontStyle: "italic" }}>No candidates registered.</p>;

  return (
    <table style={{ width: "100%", borderCollapse: "collapse" }}>
      <thead>
        <tr style={{ background: "#f1f1f1" }}>
          <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
          <th style={{ padding: "8px", textAlign: "left" }}>Position</th>
          <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
          <th style={{ padding: "8px", textAlign: "left" }}>Forms</th>
          <th style={{ padding: "8px", textAlign: "center" }}>Status</th>
          <th style={{ padding: "8px", textAlign: "center" }}>Actions</th>
        </tr>
      </thead>
      <tbody>
        {candidates.map((c) => (
          <tr
            key={c.id}
            style={{
              borderTop: "1px solid #eee",
              backgroundColor: c.approved
                ? "#e6ffe6"
                : !c.documents || c.documents.length === 0
                ? "#ffe6e6"
                : "#fff",
            }}
          >
            <td style={{ padding: "8px" }}>{c.name}</td>
            <td style={{ padding: "8px" }}>{c.position}</td>
            <td style={{ padding: "8px" }}>{c.party || "-"}</td>
            <td style={{ padding: "8px" }}>
              {c.documents && c.documents.length > 0 ? (
                c.documents.map((doc, index) => (
                  <div key={index}>
                    <a
                      href={`${process.env.REACT_APP_SERVER_URL || "http://localhost:4000"}/uploads/candidate-docs/${doc}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      style={{ color: "#007bff", textDecoration: "underline" }}
                    >
                      Form {index + 1}
                    </a>
                  </div>
                ))
              ) : (
                <span
                  style={{
                    color: "#dc3545",
                    fontStyle: "italic",
                    fontWeight: "bold",
                  }}
                >
                  No form submitted
                </span>
              )}
            </td>
            <td
              style={{
                padding: "8px",
                textAlign: "center",
                fontWeight: "bold",
                color: c.approved ? "green" : "orange",
              }}
            >
              {c.approved ? "Approved" : "Pending"}
            </td>
            <td style={{ padding: "8px", textAlign: "center" }}>
              <button
                onClick={() => onApprove(c.id)}
                disabled={c.approved || !c.documents || c.documents.length === 0}
                style={{
                  marginRight: "5px",
                  background:
                    c.approved || !c.documents || c.documents.length === 0
                      ? "#6c757d"
                      : "#28a745",
                  color: "#fff",
                  border: "none",
                  borderRadius: "6px",
                  padding: "5px 10px",
                  cursor:
                    c.approved || !c.documents || c.documents.length === 0
                      ? "not-allowed"
                      : "pointer",
                }}
              >
                {c.approved
                  ? "Approved"
                  : !c.documents || c.documents.length === 0
                  ? "No Form"
                  : "Approve"}
              </button>
              <button
                onClick={() => onDelete(c.id)}
                style={{
                  background: "#dc3545",
                  color: "#fff",
                  border: "none",
                  borderRadius: "6px",
                  padding: "5px 10px",
                  cursor: "pointer",
                }}
              >
                Delete
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

// ---------------- Election Results ----------------
const ElectionResults = ({
  elections,
  selectedElection,
  selectedElectionVotingOpen,
  results,
  winners,
  onElectionChange,
}) => {
  return (
    <div>
      {/* Election Dropdown */}
      {elections.length > 0 && (
        <div style={{ marginBottom: "15px" }}>
          <label htmlFor="electionSelect" style={{ marginRight: "10px", fontWeight: "bold" }}>
            Select Election:
          </label>
          <select
            id="electionSelect"
            value={selectedElection || ""}
            onChange={(e) => onElectionChange(parseInt(e.target.value))}
            style={{ padding: "5px 10px", borderRadius: "6px" }}
          >
            {elections.map((el) => {
              const start = el.startsAt ? new Date(el.startsAt).toLocaleString() : "N/A";
              const end = el.votingOpen
                ? "Ongoing"
                : el.endsAt
                ? new Date(el.endsAt).toLocaleString()
                : "Closed";
              return (
                <option key={el.id} value={el.id}>
                  {el.name} ({start} - {end})
                </option>
              );
            })}
          </select>
        </div>
      )}

      {/* Results Table */}
      {Object.keys(results).length === 0 ? (
        <p style={{ color: "#777", fontStyle: "italic" }}>No results yet.</p>
      ) : (
        Object.keys(results).map((pos) => (
          <div key={pos} style={{ marginBottom: "20px" }}>
            <h3 style={{ marginBottom: "8px" }}>{pos}</h3>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ background: "#f1f1f1" }}>
                  <th style={{ padding: "8px", textAlign: "left" }}>Name</th>
                  <th style={{ padding: "8px", textAlign: "left" }}>Party</th>
                  <th style={{ padding: "8px", textAlign: "center" }}>Votes</th>
                  <th style={{ padding: "8px", textAlign: "center" }}>Status</th>
                </tr>
              </thead>
              <tbody>
                {results[pos].map((c) => (
                  <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                    <td style={{ padding: "8px" }}>{c.name}</td>
                    <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                    <td style={{ padding: "8px", textAlign: "center" }}>{c.votes}</td>
                    <td
                      style={{
                        padding: "8px",
                        textAlign: "center",
                        fontWeight: "bold",
                      }}
                    >
                      {!selectedElectionVotingOpen && winners[pos]?.id === c.id ? (
                        <span style={{ color: "green" }}>Winner</span>
                      ) : (
                        "—"
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ))
      )}
    </div>
  );
};

// ---------------- Main Admin Dashboard ----------------
export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [message, setMessage] = useState("");
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [selectedElectionVotingOpen, setSelectedElectionVotingOpen] = useState(false);

  const { logout, token } = useContext(AuthContext);
  const navigate = useNavigate();

  // ---------------- Error handler ----------------
  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    } else {
      setMessage(err.response?.data?.error || err.message);
    }
  };

  // ---------------- API Calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchElections = async () => {
    try {
      const res = await api.get("/admin/elections");
      const sorted = res.data.sort((a, b) => new Date(b.startsAt) - new Date(a.startsAt));
      setElections(sorted);

      if (sorted.length > 0) {
        const firstElection = sorted[0];
        setSelectedElection(firstElection.id);
        setSelectedElectionVotingOpen(firstElection.votingOpen);
        fetchResults(firstElection.id);
      }
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchResults = async (electionId) => {
    try {
      const res = await api.get("/admin/results", { params: { electionId } });
      setResults(res.data.positionResults || {});
      setWinners(res.data.winners || {});
    } catch (err) {
      handleApiError(err);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
      setMessage(`Voting is now ${res.data.votingOpen ? "OPEN" : "CLOSED"}`);
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      handleApiError(err);
    }
  };

  const approveCandidate = async (id) => {
    try {
      await api.post(`/admin/approve-candidate/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      handleApiError(err);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      handleApiError(err);
    }
  };

  const handleElectionChange = (id) => {
    const election = elections.find((el) => el.id === id);
    setSelectedElection(id);
    setSelectedElectionVotingOpen(election?.votingOpen ?? false);
    fetchResults(id);
  };

  // ---------------- Initial Load ----------------
  useEffect(() => {
    if (!token) {
      navigate("/login");
      return;
    }
    const init = async () => {
      await fetchVotingState();
      await fetchPendingUsers();
      await fetchCandidates();
      await fetchLogs();
      await fetchElections();
    };
    init();
  }, [token]);

  return (
    <div style={{ minHeight: "100vh", backgroundColor: "#f4f6f8", padding: "30px", fontFamily: "Arial, sans-serif" }}>
      {/* Header */}
      <header style={{
        marginBottom: "30px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        background: "#fff",
        padding: "15px 25px",
        borderRadius: "12px",
        boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
      }}>
        <h1 style={{ fontSize: "1.8rem", margin: 0, color: "#333" }}>iVote Admin Dashboard</h1>
        <button
          onClick={() => { logout(); navigate("/login"); }}
          style={{
            padding: "10px 18px",
            borderRadius: "8px",
            border: "none",
            backgroundColor: "#dc3545",
            color: "#fff",
            cursor: "pointer",
            fontWeight: "bold"
          }}
        >
          Logout
        </button>
      </header>

      <main style={{ maxWidth: "1000px", margin: "0 auto" }}>
        <Card title="Voting Status">
          <p style={{ fontWeight: "bold", color: votingOpen ? "green" : "red" }}>
            {votingOpen ? "Open" : "Closed"}
          </p>
          <button
            onClick={toggleVoting}
            style={{
              marginTop: "10px",
              padding: "10px 20px",
              borderRadius: "8px",
              border: "none",
              backgroundColor: votingOpen ? "#dc3545" : "#28a745",
              color: "#fff",
              cursor: "pointer",
              fontWeight: "bold"
            }}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </Card>

        <Card title="Pending Voter Registrations">
          <PendingUsersTable users={pendingUsers} onApprove={approveUser} onReject={rejectUser} />
        </Card>

        <Card title="Candidates">
          <CandidatesTable candidates={candidates} onApprove={approveCandidate} onDelete={deleteCandidate} />
        </Card>

        <Card title="Election Results">
          <ElectionResults
            elections={elections}
            selectedElection={selectedElection}
            selectedElectionVotingOpen={selectedElectionVotingOpen}
            results={results}
            winners={winners}
            onElectionChange={handleElectionChange}
          />
        </Card>

        <Card title="Reports">
          <button
            onClick={generateReport}
            style={{
              padding: "10px 18px",
              borderRadius: "8px",
              border: "none",
              backgroundColor: "#007bff",
              color: "#fff",
              cursor: "pointer",
              fontWeight: "bold"
            }}
          >
            Generate Final Report
          </button>
          {reportHash && (
            <p style={{ marginTop: "10px", fontSize: "0.9rem", color: "#555" }}>
              Cryptographic Hash: <span style={{ fontFamily: "monospace" }}>{reportHash}</span>
            </p>
          )}
        </Card>

        {message && (
          <p style={{
            textAlign: "center",
            color: message.toLowerCase().includes("fail") ? "red" : "green",
            fontWeight: "bold",
            marginTop: "20px"
          }}>
            {message}
          </p>
        )}
      </main>
    </div>
  );
}
